/* Element rules go in the `base` cascade layer, where Tailwind keeps its
   reset: the module styles its components and pages in `components.backend`,
   a later layer, so these never restyle the packaged buttons and inputs. A
   rule outside a layer beats every layered one, whatever its selector. The
   order statement is the module's own. The classes below are this app's. */
@layer theme, base, components, utilities;

@layer base {
  :root { color-scheme: light dark; font-family: system-ui, sans-serif; }
  /* An explicit page colour pair: the scheme's own canvas and text, which a
     contrast checker can then read instead of assuming white. */
  body { margin: 0; line-height: 1.6; background: Canvas; color: CanvasText; }
  main { padding: 2.5rem 1.25rem; }
  nav { display: flex; gap: 1rem; align-items: center; }
  .page { max-width: 52rem; margin: 0 auto; display: flex; flex-direction: column; gap: 1.5rem; }
  nav a { color: inherit; }
  h1 { letter-spacing: -0.02em; margin: 0; }
  section { border: 1px solid color-mix(in srgb, currentColor 15%, transparent); border-radius: 10px; padding: 1.25rem; display: flex; flex-direction: column; gap: 0.75rem; }
  button { padding: 0.45rem 0.8rem; border-radius: 8px; border: 1px solid color-mix(in srgb, currentColor 20%, transparent); background: none; color: inherit; font: inherit; cursor: pointer; }
  button.primary { background: CanvasText; border-color: CanvasText; color: Canvas; font-weight: 600; }
  input, select { padding: 0.45rem 0.6rem; border-radius: 8px; border: 1px solid color-mix(in srgb, currentColor 20%, transparent); background: none; color: inherit; font: inherit; }
  ul { margin: 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 0.4rem; }
  li { display: flex; align-items: center; gap: 0.6rem; }
}

.muted { opacity: 0.65; font-size: 0.9rem; }
.row { display: flex; gap: 0.5rem; align-items: center; flex-wrap: wrap; }
.spacer { flex: 1; }

